using LittleLeo.Events;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RefreshingHeadbuttAction", menuName = "Data/Battle/Battle Actions/Cellarius/RefreshingHeadbutt Action")]
public class RefreshingHeadbuttAction : PurifyMinimunWaveAction
{
	[Header("Reset Used Runes")]
	[SerializeField]
	private VoidEvent OnResetUsedRunes;

	[SerializeField]
	private RefreshAction refreshAction;

	public RefreshAction RefreshAction => refreshAction;

	public override void MinimunWaveAction(GameObject source)
	{
		OnResetUsedRunes.Raise();
	}
}
